const crypto = require('crypto');

function checkToken(submitted, stored) {
  const a = Buffer.from(submitted);
  const b = Buffer.from(stored);
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

const stored = 'a1b2c3d4';
console.log(checkToken('a1b2c3d4', stored) ? 'GRANT' : 'DENY');
console.log(checkToken('a1b2c3d9', stored) ? 'GRANT' : 'DENY');

